import logo from './logo.svg';
import './App.css';
import { useEffect, useState } from 'react';
import { type } from '@testing-library/user-event/dist/type';

function App() {

  const setVh = () => {
    const vh = window.innerHeight * 0.01;   // [1]
    document.documentElement.style.setProperty('--vh', `${vh}px`); // [2]
  }

  useEffect(()=>{
    setVh()

    function onResize(){
      setVh()
    }

    window.addEventListener('resize', onResize)
  }, [])

  const [page, setPage] = useState(0)

  const questionList = [
    {q:['오늘이 몇 월이고, 무슨 요일인지를 잘 모른다.'],
    a:[{type:'Yes', text:'네'},
       {type:'No', text:'아니요'}]},
    
    {q:['자기가 놓아둔 물건을 찾지 못한다.'],
    a:[{type:'Yes', text:'네'},
       {type:'No', text:'아니요'}]},

    {q:['같은 질문을 반복해서 한다.'],
    a:[{type:'Yes', text:'네'},
       {type:'No', text:'아니요'}]},

    {q:['약속을 하고서 잊어버린다.'],
    a:[{type:'Yes', text:'네'},
       {type:'No', text:'아니요'}]},
    
    {q:['물건을 가지러 갔다가 잊어버리고 그냥 온다.'],
    a:[{type:'Yes', text:'네'},
       {type:'No', text:'아니요'}]},

    {q:['물건이나 사람의 이름을 대기가 힘들어 머뭇거린다.'],
    a:[{type:'Yes', text:'네'},
       {type:'No', text:'아니요'}]},

    {q:['대화 중 내용이 이해되지 않아 반복해서 물어본다.'],
    a:[{type:'Yes', text:'네'},
       {type:'No', text:'아니요'}]},
    
    {q:['길을 잃거나 헤맨 적이 있다.'],
    a:[{type:'Yes', text:'네'},
       {type:'No', text:'아니요'}]},

    {q:['예전에 비해 계산능력이 떨어졌다. (예: 물건값이나 거스름돈 계산을 못한다.)'],
    a:[{type:'Yes', text:'네'},
       {type:'No', text:'아니요'}]},

    {q:['예전에 비해 성격이 변했다.'],
    a:[{type:'Yes', text:'네'},
       {type:'No', text:'아니요'}]},

    {q:['이전에 잘 다루던 기구의 사용이 서툴러졌다.(세탁기, 전기밥솥, 경운기 등'],
    a:[{type:'Yes', text:'네'},
       {type:'No', text:'아니요'}]},
    
    {q:['예전에 비해 방이나 집안의 정리정돈을 하지 못한다.'],
    a:[{type:'Yes', text:'네'},
       {type:'No', text:'아니요'}]},

    {q:['상황에 맞게 스스로 옷을 선택하여 입지 못한다.'],
    a:[{type:'Yes', text:'네'},
       {type:'No', text:'아니요'}]},

    {q:['혼자 대중교통수단을 이용해 목적지에 가기 힘들다.(관절염 등의 신체적인 문제로 인한 것은 제외)'],
    a:[{type:'Yes', text:'네'},
       {type:'No', text:'아니요'}]},
    
    {q:['내복이나 옷이 더러워져도 갈아입지 않으려고 한다.'],
    a:[{type:'Yes', text:'네'},
       {type:'No', text:'아니요'}]},

    {q:['테스트가 모두 끝났어요. 결과를 볼까요?'],
    a:[{type:'', text:'결과 보러 가기'}]
    }


  ]

  const [resultList,setResultList] = useState([
    {name: 'Yes', count:0}, {name: 'No', count:0}
  ])

  const handleCkAnswer = (type, idx) => {
    let ls = resultList
    for(let i = 0; i < ls.length; i++ ){
      if(ls[i].name===type){
        ls[i].count = ls[i].count + 1
      }
    }

    setResultList(ls)
    setPage(page+1)

    if(idx+1 == questionList.length){
      console.log('결과보기')
    }
  }


  return (
    <div className="silverlayout">
      {page===0?  //page가 0이면 시작페이지로, 0이 아니면 테스트페이지를 보여주는 문법
      <div className='startPageLayout'>
        <div className='startLogo'>
          <div>치매 검사와 예방을 한번에</div>
          <div>스마트 치매 지킴이</div>
          <div>김민걸바보</div>
          <div>▼</div>
        </div>
        <div onClick={()=>setPage(1)} className='startButton'>시작하기</div>  
      </div>
      :page <= questionList.length?
      <div className='questionLayout'>
        <div className='dementiaTitle'>
          <div>치매 위험도 테스트</div>
          <div>{`${page} / ${questionList.length}`}</div>
        </div>

        {questionList.map((val, idx)=>
          <div className='questionList' style={{display:page===idx+1?'flex':'none'}} key={idx}>
            {console.log(resultList)}
            <div className='questionItemLayout'>
              <div className='profileImg'>
                <div>^_^</div>
              </div>

              <div className='chatListLayout'>
                {val.q.map((qval, qidx)=>
                  <div key={qidx} className='chatBox'>
                    <div>◀</div> <div>{qval}</div>
                  </div>
                )}
              </div>
            </div>
            <div className='answerItemLayout'>
              <div className='aChatBox'>
                <div>+</div> <div>+</div>
              </div>

              {val.a.map((aval, aidx)=>
                <div key={aidx} className='answerBox' onClick={() => handleCkAnswer(aval.type, idx)}>
                  {aval.text}
                </div>
              )}
            </div>
          </div>
        )}
      </div>
      :
      <div>
        결과 페이지
      </div>
      }
    </div>
  );
}

export default App;
